out = Path(__file__).with_name('retrain_prompts.jsonl')
with out.open('w', encoding='utf-8') as f:
    for p,c in pairs:
        json.dump({'prompt': p, 'completion': c, 'pair_type': 'sft', 'origin': 'generated'}, f, ensure_ascii=False)
        f.write('\n')
print(f"Wrote {out} with {len(pairs)} records")
